// Four numbers: find three integers x (each between 1 and 10) such that every
// input number can be generated by summing some subset of x.
import org.maxicp.cp.engine.core.CPBoolVar;
import org.maxicp.cp.engine.core.CPIntVar;
import static org.maxicp.cp.CPFactory.*;
import dcp.Instance;
import dcp.Model;
import dcp.Outputs;

public class Submission {
  public static void build(Instance inst, Model m, Outputs out) {
    // the input numbers, up to four, read from the instance
    int[] numbers = inst.getIntArray("numbers");

    // the three integers x, each between 1 and 10 inclusive
    CPIntVar[] x = m.intVarArray(3, 1, 10);

    // one sum variable per non-empty subset of x (subset k uses x[i] when bit i of k is set)
    CPIntVar[] subsetSum = new CPIntVar[7];
    for (int k = 1; k <= 7; k++) {
      int size = Integer.bitCount(k);
      CPIntVar[] members = new CPIntVar[size];
      int next = 0;
      for (int i = 0; i < 3; i++) {
        if ((k & (1 << i)) != 0) members[next++] = x[i];
      }
      // the subset sum equals the sum of its chosen integers of x
      subsetSum[k - 1] = m.intVar(1, 30);
      m.cp().post(sum(members, subsetSum[k - 1]));
    }

    // each input number is the sum of some subset of x
    for (int v : numbers) {
      // one choice per non-empty subset: its sum equals this number
      CPBoolVar[] generated = new CPBoolVar[7];
      for (int k = 0; k < 7; k++) {
        generated[k] = isEq(subsetSum[k], v);
      }
      m.cp().post(or(generated));
    }

    out.put("x", x);
  }
}
